 const uploader=financeUploadCard(result,box);hero.append(uploader.element,top);const shortcuts=el('div',undefined,{class:'finance-shortcuts'});for(const [label,kind]of [['Cadastrar nota / compra','invoice'],['Registrar pagamento já realizado','payment']]){const b=el('button',label,{type:'button',class:'secondary'});b.addEventListener('click',()=>financeForm(box,result,undefined,{kind}));shortcuts.append(b)}hero.append(shortcuts);
 const nav=el('nav',undefined,{class:'finance-section-nav','aria-label':'Áreas do financeiro'});for(const [key,label]of Object.entries(viewLabels)){const panel=el('section',undefined,{id:'finance-view-'+key,class:'finance-view','aria-label':label}),button=el('button',label,{type:'button','aria-controls':panel.id,'aria-pressed':String(financeActiveView===key)});button.addEventListener('click',()=>{financeActiveView=key;for(const [k,p]of Object.entries(panels))p.hidden=k!==key;for(const b of nav.querySelectorAll('button'))b.setAttribute('aria-pressed',String(b===button))});panel.hidden=financeActiveView!==key;panels[key]=panel;nav.append(button)}hero.append(nav);let current='reports';
